// unmarshalIntegral_IntegerLiteral_fits reports whether the Go integer type kind
// holds the integer s.
func unmarshalIntegral_IntegerLiteral_fits(s, kind string) bool {
	size := strconv.IntSize
	switch strings.TrimPrefix(kind, "u") {
	case "int8":
		size = 8
	case "int16":
		size = 16
	case "int32":
		size = 32
	case "int64":
		size = 64
	}
	if strings.HasPrefix(kind, "u") {
		_, err := strconv.ParseUint(s, 10, size)
		return err == nil
	}
	_, err := strconv.ParseInt(s, 10, size)
	return err == nil
}

// unmarshalIntegral_IntegerLiteral_number returns the integer that the number s
// holds, written without a fraction, an exponent or a plus sign, or false when s
// holds none. An integer of more than 20 digits, which no Go integer holds, is
// returned as "".
func unmarshalIntegral_IntegerLiteral_number(s string) (string, bool) {
	neg := strings.HasPrefix(s, "-")
	if neg || strings.HasPrefix(s, "+") {
		s = s[1:]
	}
	mantissa, exp := s, "0"
	if i := strings.IndexAny(s, "eE"); i >= 0 {
		mantissa, exp = s[:i], s[i+1:]
	}
	intPart, frac, _ := strings.Cut(mantissa, ".")
	digits := intPart + frac
	if digits == "" || strings.Trim(digits, "0123456789") != "" {
		return "", false
	}
	significant := strings.TrimLeft(digits, "0")
	if significant == "" {
		return "0", true
	}
	e, err := strconv.Atoi(exp)
	if err != nil && !errors.Is(err, strconv.ErrRange) {
		return "", false
	}
	// An exponent out of an int's range is read as the largest int; a billion is
	// still past any Go integer, and keeps point from overflowing.
	if e > 1e9 {
		e = 1e9
	} else if e < -1e9 {
		e = -1e9
	}
	point := len(intPart) - (len(digits) - len(significant)) + e
	significant = strings.TrimRight(significant, "0")
	if point < len(significant) {
		return "", false
	}
	if point > 20 {
		return "", true
	}
	whole := significant + strings.Repeat("0", point-len(significant))
	if neg {
		whole = "-" + whole
	}
	return whole, true
}

